		var blob = h.get_node_or_null("BlobShadow")
		var vm: Node3D = h.get("visual_mesh")
		var mesh_count := 0
		if vm != null and is_instance_valid(vm):
			mesh_count = _count_meshes(vm)
		print("[PROBE] hero=", str(h.get("display_name")), " team=", str(h.get("team")),
			" is_dead=", str(h.get("is_dead")), " meshes=", mesh_count,
			" rim_mats=", mats.size(), " blob=", blob != null,
			" blob_scale=", (blob.scale.x if blob != null else 0.0),
			" visible=", h.visible)
	print("[PROBE] camera=", get_viewport().get_camera_3d())

func _count_meshes(n: Node) -> int:
	var c := 1 if n is MeshInstance3D else 0
	for ch in n.get_children():
		c += _count_meshes(ch)
	return c
