{"content":"extends Node3D
## 临时微探针：静态场景验证 rim / 接地阴影 / 闪白的真实渲染像素。
## 完成后删除本文件、_probe_fx.tscn 与 _fx_*.png。

var heroes: Array = []

func _ready() -> void:
	DisplayServer.window_set_size(Vector2i(1280, 720))

	var we := WorldEnvironment.new()
	var env := Environment.new()
	env.background_mode = Environment.BG_COLOR
	env.background_color = Color(0.16, 0.18, 0.22)
	env.ambient_light_source = Environment.AMBIENT_SOURCE_COLOR
	env.ambient_light_color = Color(0.75, 0.8, 0.9)
	env.ambient_light_energy = 0.9
	we.environment = env
	add_child(we)

	var sun := DirectionalLight3D.new()
	sun.rotation_degrees = Vector3(-55.0, 30.0, 0.0)
	sun.shadow_enabled = true
	add_child(sun)

	var ground := MeshInstance3D.new()
	var pm := PlaneMesh.new()
	pm.size = Vector2(50.0, 50.0)
	ground.mesh = pm
	var gm := StandardMaterial3D.new()
	gm.albedo_color = Color(0.42, 0.45, 0.4)
	gm.roughness = 1.0
	ground.material_override = gm
	add_child(ground)

	var cam := Camera3D.new()
	add_child(cam)
	cam.look_at_from_position(Vector3(0.0, 7.0, 15.0), Vector3(0.0, 3.0, 0.0), Vector3.UP)
	cam.current = true

	_spawn("亚瑟", 0, -3.5)
	_spawn("小乔", 1, 0.0)
	_spawn("兰陵王", 1, 3.5)

	for i in range(20):
		await get_tree().process_frame
	# 冻结动画/物理，保证三张截图只有 FX 差异
	for h in heroes:
		h.set_physics_process(false)
		h.set_process(false)
		if h.anim_player != null:
			if h.anim_player.has_animation("idle"):
				h.anim_player.play("idle")
			h.anim_player.seek(0.25, true)
			h.anim_player.pause()
	for i in range(4):
		await get_tree().process_frame

	for h in heroes:
		var mats: Array = h.get_meta("_fx_rim_mats", [])
		var blob = h.get_node_or_null("BlobShadow")
		print("[FXPROBE] ", h.display_name, " team=", h.team, " rim=", mats.size(),
			" rim_color=", str(mats[0].get_shader_parameter("rim_color") if mats.size() > 0 else null),
			" blob=", blob != null, " blob_scale=", (blob.scale.x if blob != null else 0.0),
			" blob_visible=", (blob.visible if blob != null else false))
	await RenderingServer.frame_post_draw
	await RenderingServer.frame_post_draw
	_save("res://_fx_shot.png")

	# 基线：摘 overlay + 隐藏 blob
	var saved: Array = []
	for h in heroes:
		for m in _all_meshes(h):
			saved.append([m, m.material_overlay])
			m.material_overlay = null
		var f = h.get_node_or_null("BlobFollower")
		if f != null:
			f.set_process(false)
		var blob = h.get_node_or_null("BlobShadow")
		if blob != null:
			blob.visible = false
	await RenderingServer.frame_post_draw
	await RenderingServer.frame_post_draw
	_save("res://_fx_base.png")
	for pair in saved:
		if is_instance_valid(pair[0]):
			pair[0].material_overlay = pair[1]
	for h in heroes:
		var f = h.get_node_or_null("BlobFollower")
		if f != null:
			f.set_process(true)

	# 闪白
	for h in heroes:
		UnitVisuals.flash(h)
	await get_tree().process_frame
	await RenderingServer.frame_post_draw
	_save("res://_fx_hit.png")

	# 隐身体验：兰陵王隐身 → 阴影应隐藏（rim 仍保留）
	var llw = heroes[2]
	llw.lanling_stealth_active = true
	for i in range(3):
		await get_tree().process_frame
	print("[FXPROBE] stealth blob_visible=", llw.get_node("BlobShadow").visible, " (expect false)")
	llw.lanling_stealth_active = false
	llw.is_dead = true
	for i in range(3):
		await get_tree().process_frame
	print("[FXPROBE] dead blob_visible=", llw.get_node("BlobShadow").visible, " (expect false)")
	get_tree().quit()

func _spawn(hero_name: String, team: int, x: float) -> void:
	var h: Hero = Hero.new()
	h.setup({"name": hero_name, "team": team})
	h.is_ai = true
	h.position = Vector3(x, 0.0, 0.0)
	add_child(h)
	heroes.append(h)

func _save(path: String) -> void:
	var img := get_viewport().get_texture().get_image()
	img.save_png(path)
	print("[FXPROBE] saved ", path, " size=", img.get_size())

func _all_meshes(n: Node) -> Array:
	var out: Array = []
	if n is MeshInstance3D:
		out.append(n)
	for c in n.get_children():
		out.append_array(_all_meshes(c))
	return out
