{"content":"extends Node
## 临时探针：加载 battle.tscn（--net-test 自动开局），摆好英雄后近距离截图。
## 输出：_shot_char.png（正常，保留）、_shot_base.png（关 FX 基线）、_shot_hit.png（闪白）、_shot_debug.png（阴影几何调试）。
## 验证后删除本文件、_probe_char.tscn 与临时截图。

var battle: Node
var focus_hero: Node

func _ready() -> void:
	DisplayServer.window_set_size(Vector2i(1600, 900))
	battle = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	for i in range(600):
		await get_tree().process_frame
		if battle.hero_selected and battle.hero != null and is_instance_valid(battle.hero):
			break
	for i in range(60):
		await get_tree().process_frame
	focus_hero = battle.hero
	# 移出泉水圆盘，站到中路地面（泉水盘 y≈0.33 会遮住贴地阴影）
	focus_hero.global_position = Vector3(-30.0, 0.0, 30.0)
	for i in range(8):
		await get_tree().process_frame
	# 拉一个敌方英雄到镜头旁，验证红色 rim（探针专用）
	for h in get_tree().get_nodes_in_group("heroes"):
		if is_instance_valid(h) and h != focus_hero and int(h.get("team")) == 1:
			h.global_position = focus_hero.global_position + Vector3(3.0, 0.0, 0.0)
			h.visible = true
			break
	for i in range(4):
		await get_tree().process_frame
	# 冻结英雄物理/动画 + 关掉 battle 的相机跟随，手动摆近距离机位
	for h in get_tree().get_nodes_in_group("heroes"):
		if not is_instance_valid(h):
			continue
		h.set_physics_process(false)
		var ap = h.get("anim_player")
		if ap != null and is_instance_valid(ap):
			ap.pause()
	battle.set_process(false)
	var focus: Vector3 = focus_hero.global_position + Vector3(1.2, 0.0, 0.0)
	var cam: Camera3D = battle.cam
	if cam != null:
		cam.fov = 45.0
		cam.global_position = focus + Vector3(2.6, 2.8, 5.6)
		cam.look_at(focus + Vector3(0.0, 2.1, 0.0), Vector3.UP)
	for i in range(6):
		await get_tree().process_frame
	_dump()
	await RenderingServer.frame_post_draw
	await RenderingServer.frame_post_draw
	_save("res://_shot_char.png")

	# 基线：摘掉 rim overlay + 隐藏 BlobShadow
	var saved: Array = []
	for h in get_tree().get_nodes_in_group("heroes"):
		if not is_instance_valid(h):
			continue
		for m in _all_meshes(h):
			saved.append([m, m.material_overlay])
			m.material_overlay = null
		var f = h.get_node_or_null("BlobFollower")
		if f != null:
			f.set_process(false)
		var blob = h.get_node_or_null("BlobShadow")
		if blob != null:
			blob.visible = false
	await RenderingServer.frame_post_draw
	await RenderingServer.frame_post_draw
	_save("res://_shot_base.png")
	for pair in saved:
		if is_instance_valid(pair[0]):
			pair[0].material_overlay = pair[1]
	for h in get_tree().get_nodes_in_group("heroes"):
		if is_instance_valid(h):
			var f = h.get_node_or_null("BlobFollower")
			if f != null:
				f.set_process(true)

	# 闪白瞬间
	UnitVisuals.flash(focus_hero)
	await get_tree().process_frame
	await RenderingServer.frame_post_draw
	_save("res://_shot_hit.png")

	# 阴影几何调试：换成亮品红不透明材质
	var blob = focus_hero.get_node_or_null("BlobShadow")
	if blob != null:
		var dm := StandardMaterial3D.new()
		dm.albedo_color = Color(1.0, 0.0, 1.0)
		dm.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
		blob.material_override = dm
		await RenderingServer.frame_post_draw
		_save("res://_shot_debug.png")
	get_tree().quit()

func _save(path: String) -> void:
	var img := get_viewport().get_texture().get_image()
	img.save_png(path)
	print("[PROBE] saved ", path, " size=", img.get_size())

func _dump() -> void:
	for h in get_tree().get_nodes_in_group("heroes"):
		if not is_instance_valid(h) or h.visible == false:
			continue
		var mats: Array = h.get_meta("_fx_rim_mats", [])
		var blob = h.get_node_or_null("BlobShadow")
		print("[PROBE] ", str(h.get("display_name")), " team=", int(h.get("team")),
			" rim=", mats.size(), " rim_color=", str(mats[0].get_shader_parameter("rim_color") if mats.size() > 0 else null),
			" blob=", blob != null, " blob_y=", (blob.global_position.y if blob != null else -1.0),
			" blob_visible=", (blob.visible if blob != null else false))

func _all_meshes(n: Node) -> Array:
	var out: Array = []
	if n is MeshInstance3D:
		out.append(n)
	for c in n.get_children():
		out.append_array(_all_meshes(c))
	return out
